func (q *Queries) UpdateOrganization(ctx context.Context, arg UpdateOrganizationParams) (Organization, error) {
	row := q.db.QueryRow(ctx, updateOrganization,
		arg.ID, arg.Name,
		arg.ArinSet, arg.ArinOrgID,
		arg.AddressLine1,
		arg.Addr2Set, arg.AddressLine2,
		arg.City,
		arg.StateSet, arg.StateProvince,
		arg.PostalSet, arg.PostalCode,
		arg.Country,
		arg.PhoneSet, arg.Phone,
		arg.EmailSet, arg.Email,
		arg.AdminPocName, arg.AdminPocEmail,
		arg.APocPhoneSet, arg.AdminPocPhone,
		arg.TechPocName, arg.TechPocEmail,
		arg.TPocPhoneSet, arg.TechPocPhone,
		arg.AbusePocName, arg.AbusePocEmail,
		arg.AbPocPhoneSet, arg.AbusePocPhone,
		arg.NPocNameSet, arg.NocPocName,
		arg.NPocEmailSet, arg.NocPocEmail,
		arg.NPocPhoneSet, arg.NocPocPhone,
		arg.DescriptionSet, arg.Description)
	var o Organization
	err := scanOrg(row, &o)
	return o, err
}

const countAsnsForOrganization = `SELECT count(*)::bigint FROM bgp_asns WHERE organization_id = $1`

func (q *Queries) CountAsnsForOrganization(ctx context.Context, orgID uuid.UUID) (int64, error) {
	row := q.db.QueryRow(ctx, countAsnsForOrganization, orgID)
	var n int64
	err := row.Scan(&n)
	return n, err
}

const deleteOrganization = `DELETE FROM organizations WHERE id = $1`

func (q *Queries) DeleteOrganization(ctx context.Context, id uuid.UUID) error {
	_, err := q.db.Exec(ctx, deleteOrganization, id)
	return err
}

// ---- Collectors ----

const enrollCollector = `INSERT INTO collectors (id, site_id, name, capabilities, status,
                        enrollment_token_hash, buffered_samples, enabled,
                        config_overrides, created_at, updated_at)
VALUES (gen_random_uuid(), $1, $2, $3::jsonb, 'pending'::collector_status,
        $4, 0, true, '{}'::jsonb, NOW(), NOW())
RETURNING id, site_id`

type EnrollCollectorParams struct {
	SiteID              uuid.UUID `json:"site_id"`
	Name                string    `json:"name"`
	CapabilitiesJson    []byte    `json:"capabilities"`
	EnrollmentTokenHash string    `json:"enrollment_token_hash"`
}

type EnrollCollectorRow struct {
	ID     uuid.UUID `json:"id"`
	SiteID uuid.UUID `json:"site_id"`
}

func (q *Queries) EnrollCollector(ctx context.Context, arg EnrollCollectorParams) (EnrollCollectorRow, error) {
	row := q.db.QueryRow(ctx, enrollCollector, arg.SiteID, arg.Name, arg.CapabilitiesJson, arg.EnrollmentTokenHash)
	var r EnrollCollectorRow
	err := row.Scan(&r.ID, &r.SiteID)
	return r, err
}

const heartbeatCollector = `UPDATE collectors
SET last_seen_at      = $2::timestamptz,
    buffered_samples  = $5::int,
    version           = COALESCE($3::text, version),
    status            = $4::collector_status,
    updated_at        = NOW()
WHERE id = $1
RETURNING config_overrides`

type HeartbeatCollectorParams struct {
	ID              uuid.UUID `json:"id"`
	LastSeenAt      time.Time `json:"last_seen_at"`
	Version         *string   `json:"version"`
	Status          string    `json:"status"`
	BufferedSamples int32     `json:"buffered_samples"`
}

func (q *Queries) HeartbeatCollector(ctx context.Context, arg HeartbeatCollectorParams) ([]byte, error) {
	row := q.db.QueryRow(ctx, heartbeatCollector, arg.ID, arg.LastSeenAt, arg.Version, arg.Status, arg.BufferedSamples)
	var overrides []byte
	err := row.Scan(&overrides)
	return overrides, err
}

const insertCollectorHeartbeat = `INSERT INTO collector_heartbeats (id, collector_id, received_at,
                                  queue_depth, last_error, metrics_json,
                                  created_at, updated_at)
VALUES (gen_random_uuid(), $1, $2::timestamptz,
        $3::int, $4, $5::jsonb,
        NOW(), NOW())`

type InsertCollectorHeartbeatParams struct {
	CollectorID uuid.UUID `json:"collector_id"`
	ReceivedAt  time.Time `json:"received_at"`
	QueueDepth  int32     `json:"queue_depth"`
	LastError   *string   `json:"last_error"`
	MetricsJson []byte    `json:"metrics_json"`
}

func (q *Queries) InsertCollectorHeartbeat(ctx context.Context, arg InsertCollectorHeartbeatParams) error {
	_, err := q.db.Exec(ctx, insertCollectorHeartbeat, arg.CollectorID, arg.ReceivedAt, arg.QueueDepth, arg.LastError, arg.MetricsJson)
	return err
}

const collectorRetCols = `id, site_id, name, version, mtls_fingerprint,
          status::text AS status, capabilities,
          last_seen_at, last_ingest_at, buffered_samples, enabled,
          config_overrides, created_at, updated_at`

func scanCollector(row interface{ Scan(...any) error }, c *Collector) error {
	return row.Scan(&c.ID, &c.SiteID, &c.Name, &c.Version, &c.MtlsFingerprint,
		&c.Status, &c.CapabilitiesJson,
		&c.LastSeenAt, &c.LastIngestAt, &c.BufferedSamples, &c.Enabled,
		&c.ConfigOverridesJson, &c.CreatedAt, &c.UpdatedAt)
}

const setCollectorConfigOverrides = `UPDATE collectors
SET config_overrides = $2::jsonb, updated_at = NOW()
WHERE id = $1
RETURNING ` + collectorRetCols

type SetCollectorConfigOverridesParams struct {
	ID              uuid.UUID `json:"id"`
	ConfigOverrides []byte    `json:"config_overrides"`
}

func (q *Queries) SetCollectorConfigOverrides(ctx context.Context, arg SetCollectorConfigOverridesParams) (Collector, error) {
	row := q.db.QueryRow(ctx, setCollectorConfigOverrides, arg.ID, arg.ConfigOverrides)
	var c Collector
	err := scanCollector(row, &c)
	return c, err
}

const setCollectorEnabled = `UPDATE collectors
SET enabled = $2, updated_at = NOW()
WHERE id = $1
RETURNING ` + collectorRetCols

type SetCollectorEnabledParams struct {
	ID      uuid.UUID `json:"id"`
	Enabled bool      `json:"enabled"`
}

func (q *Queries) SetCollectorEnabled(ctx context.Context, arg SetCollectorEnabledParams) (Collector, error) {
	row := q.db.QueryRow(ctx, setCollectorEnabled, arg.ID, arg.Enabled)
	var c Collector
	err := scanCollector(row, &c)
	return c, err
}

const decommissionCollector = `UPDATE collectors
SET status = 'decommissioned'::collector_status, updated_at = NOW()
WHERE id = $1
RETURNING ` + collectorRetCols

func (q *Queries) DecommissionCollector(ctx context.Context, id uuid.UUID) (Collector, error) {
	row := q.db.QueryRow(ctx, decommissionCollector, id)
	var c Collector
	err := scanCollector(row, &c)
	return c, err
}
